head.script:
    scwin.onpageload = function() {
        var jsonData = [{col1:"a",col3:"a"},{col1:"c",col3:"c"},{col1:"d",col3:"d"},{col1:"b",col3:"b"}];
        dataList1.setJSON(jsonData);
    };

    scwin.onpageunload = function() {

    };


    scwin.gridView1_ongroupby = function(options) {
        scwin.test(options);
    };
    scwin.test = function(options){
        //debugger;
        var flag = true;
        if(flag) {
            options.closeGroup = true; 

            options.groupbyHeader = [{colSpan: "3", inputType: "expression", expression: " toggle() + depthStr() + ' [ ' + count() + ' 건 ] ' ", align: "left" }];
            options.groupbyFooter = [
                {colSpan:"3",inputType: "expression", expression: " SUM('col2')", displayFormatter: "countFormatFunction", align: "center"}
            ];

            gridView1.groupby( options ); //실제 groupby 실행

        } else {
            return false; 
        }
    }
    var countFormatFunction = function( value ) {
        return "총판매수량 : " + value + " 개 ";
    };

	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate = function() {
		scwin.simulateWrapper('#gridView1_column3', 'drag-n-drop', {
			dx: 0,
			dy: -50
		});
	}

	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('gridView1_customFilter').style.display == 'block';
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_column3').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
		WebSquare.wUnit.addCommand("pause", "500");


		WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2grid_groupbyZone_column')[0].click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_groupbyZone_list_items_main').children[0].click()");
		WebSquare.wUnit.addCommand("pause", "400");

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_btnConform_column3').click()");
		WebSquare.wUnit.addCommand("pause", "400");		

		WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2grid_groupbyZone_column')[0].click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_groupbyZone_list_items_main').children[0].click()");
		WebSquare.wUnit.addCommand("pause", "400");	

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");			

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
